INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('P3-stack-mae-correction', 'P', 'CORRECTION of P1: the conviction-stack export carried one row PER UNIT, so payout_sim checked each unit''s MAE sequentially instead of the position''s', 'NQ', '2020–2026', NULL, NULL, NULL, NULL, 'invalid', 'Re-run on Select Daily 50K, 2020-01-15→2026-10-09, same book: per-unit rows reproduce P1 (65% of 2-wk windows, 0.9 blown/yr, funded 90%); the stack as ONE position (summed MAE: median $220, p90 $1,542, p99 $3,882 vs a $2,000 trail) → 1% of windows, 11.9 blown/yr, funded 8%; 1 MNQ flat 13% of windows, 2.8 blown/yr; half-size stack 6%, 5.5/yr. "Bigger stacks are safer" was the artefact. The overnight book does not fit a Tradeify drawdown at any size. P1 is superseded.', '2026-10-11'),
('P2-venue-comparison', 'P', 'Overnight conviction book (correct MAE) under venues that allow the hold: FTMO 2-step Swing $100k (US100 CFD: 10%/5% targets, 5% daily on equity, 10% static, 14-day payouts 80%, +$5/unit/night CFD cost ASSUMED) and Phidias Premium 100K (CME futures, overnight+weekend, $6k target, $3k EOD trail ASSUMED locking at +$100, 30% consistency, 5-day payouts, buffer kept above the lock)', 'NQ', '2019–2026 / 2010–2026', NULL, NULL, NULL, NULL, 'weak', 'FTMO 100k x1 (1–4 MNQ-equiv, 0.2–0.8 lots): 2019–26 27% of fortnights paid, $688/month, 0.6 blown/yr, funded 61% (the 15% two-phase eval takes ~1.5 yr at this size); 2010–26 15% / $386 / 0.3. Any larger size blows on the 2022 drawdown (x2 8/yr). Phidias x1: 8% of fortnights, $237/month, 2.4 blown/yr (realised drawdowns > $3k). Tradeify ref: 1%. No venue turns the book into a weekly payer; FTMO 100k at minimum size is the only positive-EV fit (~$700/month, a payout every ~7 weeks).', '2026-10-11')
